import org.jetbrains.kotlin.gradle.dsl.JvmTarget

// The data APIs' Kotlin SDK: every source is generated by common/codegen from common/specs.
plugins {
    `java-library`
    id("org.jetbrains.kotlin.jvm") version "2.3.0"
    kotlin("plugin.serialization") version "2.3.0"
}

group = "it.attendance100.mybicocca.data.remote"
version = "0.1"

dependencies {
    // Ktor HTTP client, and the JSON and HTML types the generated APIs expose
    api("io.ktor:ktor-client-core:3.3.3")
    api("io.ktor:ktor-serialization-kotlinx-json:3.3.3")
    api("org.jsoup:jsoup:1.18.3")
    api("org.jetbrains.kotlinx:kotlinx-coroutines-core:1.10.2")
    implementation("io.ktor:ktor-client-content-negotiation:3.3.3")
    implementation("io.ktor:ktor-client-okhttp:3.3.3")

    testImplementation(kotlin("test"))
    // JUnit reads the return type of suspending test functions through Kotlin reflection.
    testImplementation(kotlin("reflect"))
    testImplementation(platform("org.junit:junit-bom:6.0.1"))
    testImplementation("org.junit.jupiter:junit-jupiter")
    testImplementation("org.junit.platform:junit-platform-suite")
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
    testImplementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.10.2")
    testImplementation("io.ktor:ktor-client-mock:3.3.3")
    testImplementation("io.ktor:ktor-client-logging:3.3.3")
    testImplementation("org.slf4j:slf4j-simple:2.0.17")
}

kotlin {
    compilerOptions {
        jvmTarget.set(JvmTarget.JVM_17)
    }
}

java {
    sourceCompatibility = JavaVersion.VERSION_17
    targetCompatibility = JavaVersion.VERSION_17
}

tasks.test {
    useJUnitPlatform {
        excludeTags("live")
    }
}

// The live tests, generated from each API's tests.yaml, call the real services: see "Live tests"
// in common/codegen/README.md. Pick an API's with --tests, e.g. --tests '*.esse3.live.*'.
val liveTest by tasks.registering(Test::class) {
    description = "Runs the live tests against the real services."
    group = "verification"
    testClassesDirs = sourceSets.test.get().output.classesDirs
    classpath = sourceSets.test.get().runtimeClasspath
    useJUnitPlatform {
        includeTags("live")
    }
    environment("LIVE_TESTS", "1")
    // Every run talks to the servers again, whatever changed.
    outputs.upToDateWhen { false }
}
